validation_checklist.command:
python - <<'EOF'
import json, glob
from features.main.container import AppContainer
c = AppContainer.build()
reg = set(getattr(c.side_effect_engine, '_handlers', {}).keys())
node_types = set()
for f in glob.glob('core/engine/workflow/nodes/*.json'):
    d = json.load(open(f))
    def walk(o):
        if isinstance(o, dict):
            for se in o.get('side_effects', []) or []:
                node_types.add(se.get('type') if isinstance(se, dict) else se)
                for comp in (se.get('compensation', []) if isinstance(se, dict) else []) or []:
                    node_types.add(comp.get('type') if isinstance(comp, dict) else comp)
            for v in o.values(): walk(v)
        elif isinstance(o, list):
            for v in o: walk(v)
    walk(d)
print('MISSING:', sorted(node_types - reg) or 'NINGUNO')
EOF
